// === Tab: mySketch ===
let agents = [];
let numAgents = 30;
let a = 1; 
let margin = 100;

function setup() {
  createCanvas(1000, 1000);
  colorMode(RGB, 1.0, 1.0, 1.0, 255);
  background(1.0, 1.0, 1.0);

  for (let i = 0; i < 10; i++) {
    let c = color(1.0, 1.0, 0.0);
    let pos = createVector(random(2 * margin, width - 2 * margin), random(2 * margin, height - 2 * margin));
    let mom = createVector(0.0, 0.0);
    agents[i] = new Agent(pos, mom, random(2.0, 7.0), c);
  }

  for (let i = 10; i < 20; i++) {
    var c = color(1.0, 1.0, 1.0);
    var pos = createVector(random(2 * margin, width - 2 * margin), random(2 * margin, height - 2 * margin));
    var mom = createVector(0.0, 0.0);
    agents[i] = new Agent(pos, mom, random(2.0, 7.0), c);
  }

  for (let i = 20; i < numAgents; i++) {
    var c = color(0.0, 0.0, 0.0);
    var pos = createVector(random(2 * margin, width - 2 * margin), random(2 * margin, height - 2 * margin));
    var mom = createVector(0.0, 0.0);
    agents[i] = new Agent(pos, mom, random(2.0, 7.0), c);
  }
}

function draw() {
  //background(1.0, 1.0, 1.0);
  fill(1.0, 1.0, 1.0, 1);

  for (let i = 0; i < numAgents; i++) {
    agents[i].display();
    let dp = Guassian();
    dp.mult(0.5);
    agents[i].evolve(dp);
  }
}

class Agent {
  constructor(position, momentum, r, ellipseColor) {
    this.q = position;
    this.p = momentum;
    this.radius = r;
    this.diameter = 2 * r;
    this.c = ellipseColor;
    this.r = red(this.c);
    this.g = green(this.c);
    this.b = blue(this.c);
  }

  evolve(dp) {
    if (this.q.x > width - margin && dp.x > 0) {
      dp.x = -dp.x;
    }
    if (this.q.x < margin && dp.x < 0) {
      dp.x = -dp.x;
    }
    if (this.q.y > height - margin && dp.y > 0) {
      dp.y = -dp.y;
    }
    if (this.q.y < margin && dp.y < 0) {
      dp.y = -dp.y;
    }

    this.p.add(dp);
    this.p.normalize();
    this.p.mult(3.0);
    this.q.add(this.p);

    let temp = this.diameter + random(-1, 1);

    if (temp > 0.0 && temp < 4 * this.radius) {
      this.diameter = temp;
    }
  }

  display() {
    fill(this.c);
    noStroke();
    ellipse(this.q.x, this.q.y, this.diameter, this.diameter);
  }
}

function Guassian() {
  let R = sqrt(-2 * log(random(1)));
  let theta = 2 * PI * random(1);

  //Box–Muller method 
  return createVector(R * cos(theta), R * sin(theta));  
}

